head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[util > M > getComponentById]<br/>지정한 ID 에 해당하는 WebSquare 컴포넌트 객체를 찾아 반환합니다.",
    "validation" : [
        "id(필수) 파라미터로 찾을 WebSquare 컴포넌트의 ID 를 설정할 수 있어야 합니다.",
        "ID 에 해당하는 WebSquare 컴포넌트 객체를 반환해야 합니다.",
        "해당 ID 의 컴포넌트가 없으면 undefined 를 반환해야 합니다.",
    ]
}



// comp 생성
scwin.comp_init = async function () {
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }
    if (typeof target2 !== 'undefined') {
        target2.remove();
    }

    let ns = $c.gcm.getNameSpace();
    let grp_comp = $c.gcm.getTestGroup();

    let strTxt = '<w2:textbox ' + ns + ' label="target1 (textbox)" style="width:200px;"></w2:textbox>';
    await $p.dynamicCreate('target1', 'textbox', strTxt, grp_comp);

    let strBtn = '<w2:button ' + ns + ' label="target2 (button)" class="tc_btn_basic" style=""></w2:button>';
    await $p.dynamicCreate('target2', 'button', strBtn, grp_comp);
}



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 동적 생성
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.btn_getComponentById_onclick = function () {
    let id = par_id.getValue();

    let comp = WebSquare.util.getComponentById(id);

    if (comp !== undefined) {
        let result = [];
        result.push("반환 타입 : " + typeof comp);
        result.push("컴포넌트 ID : " + (comp.id || "N/A"));        
        wf_body_bottom.getObj("scwin").setReturnValue(result.join(", "));
    } else {
        wf_body_bottom.getObj("scwin").setReturnValue("반환값 : undefined (컴포넌트 없음)");
    }
}
